 static Sprite square,wall,doorArt;static Material material;static float[] levels={0,7.6f,11.6f,15.6f};const float Height=19.6f;
 static Transform G(string n,Transform parent,Vector2 p){var t=new GameObject(n).transform;t.SetParent(parent,false);t.position=p;return t;}
 static GameObject B(string n,Vector2 p,Vector2 size,int color,int order,Transform parent,bool solid=false){var t=G(n,parent,p);t.localScale=new Vector3(size.x,size.y,1);var r=t.gameObject.AddComponent<SpriteRenderer>();r.sprite=square;r.sharedMaterial=material;r.color=RecoilPrototype.Hex(color);r.sortingOrder=order;if(solid)t.gameObject.AddComponent<BoxCollider2D>();return t.gameObject;}
