 internal static void RebuildStair(WalkableStairway s,float low,float high,bool exterior){
  var points=s.routePoints;float x=points[0].position.x;points[0].position=new Vector2(x,low);points[1].position=new Vector2(x+(exterior?-1:1)*5.8f,(low+high)/2);points[2].position=new Vector2(x,high);
  foreach(var t in s.transform.Cast<Transform>().ToArray())if(!points.Contains(t))UnityEngine.Object.DestroyImmediate(t.gameObject);
  var root=s.transform;for(int i=1;i<points.Length;i++){Vector2 a=points[i-1].position,b=points[i].position;Bar("Load-bearing stringer",a-Vector2.up*.18f,b-Vector2.up*.18f,.16f,0x374344,-1,root);int count=Mathf.CeilToInt(Mathf.Max((b.y-a.y)/.17f,Mathf.Abs(b.x-a.x)/.32f));for(int k=0;k<count;k++){var p=Vector2.Lerp(a,b,(k+.5f)/count);B("Grated steel tread",p-Vector2.up*.045f,new Vector2(Mathf.Abs(b.x-a.x)/count+.06f,.075f),0x7b8580,1,root);B("Tread front edge",p,new Vector2(Mathf.Abs(b.x-a.x)/count+.03f,.023f),0xa4a899,2,root);}Bar("Upper handrail",a+Vector2.up*.98f,b+Vector2.up*.98f,.065f,0x63716a,2,root);Bar("Middle safety rail",a+Vector2.up*.48f,b+Vector2.up*.48f,.035f,0x4c5c55,1,root);for(int k=0;k<=7;k++){var p=Vector2.Lerp(a,b,k/7f);B("Guardrail upright",p+Vector2.up*.49f,new Vector2(.045f,.98f),0x58675f,1,root);}}
  Vector2 turn=points[1].position;var halfLanding=B("Half landing",turn-Vector2.up*.1f,new Vector2(1.25f,.2f),0x55635e,1,root,true);if(exterior){halfLanding.AddComponent<SoftRoofPlatform>();halfLanding.GetComponent<BoxCollider2D>().isTrigger=true;}B("Landing rail",turn+Vector2.up*.95f,new Vector2(1.25f,.07f),0x63716a,2,root);
 }
 static void DoorArtwork(RecoilDoor door,float floor){foreach(var r in door.GetComponentsInChildren<SpriteRenderer>(true).ToArray())UnityEngine.Object.DestroyImmediate(r.gameObject);door.transform.position=new Vector2(door.transform.position.x,floor+1.25f);Art("Old steel fire door - artwork",doorArt,new Vector2(door.transform.position.x,floor+1.45f),new Vector2(1.55f,2.9f),door.transform,3);}
 static void Window(Transform parent,float x,float y,bool tall){float h=tall?2.45f:1.65f;B("Window recessed lintel",new Vector2(x,y+.04f),new Vector2(2.5f,h+.24f),0x191e1e,-7,parent);B("Dirty office glazing",new Vector2(x,y),new Vector2(2.2f,h),0x263b3e,-6,parent);for(int i=-1;i<=1;i+=2)B("Steel window jamb",new Vector2(x+i*1.14f,y),new Vector2(.065f,h+.08f),0x777b70,-5,parent);B("Window centre mullion",new Vector2(x,y),new Vector2(.045f,h),0x626d65,-5,parent);B("Window sill",new Vector2(x,y-h/2-.09f),new Vector2(2.58f,.12f),0x777b70,-5,parent);B("Transom",new Vector2(x,y+.2f),new Vector2(2.2f,.045f),0x626d65,-5,parent);}
 static void OfficeDoor(Transform parent,float x,float floor,string id){var root=G("Office partition door - E to open",parent,new Vector2(x,floor+1.2f));B("Upper partition",new Vector2(x,floor+3.2f),new Vector2(.2f,1.6f),0x888a78,-1,root,true);var barrier=B("Door collision - disabled when open",new Vector2(x,floor+1.2f),new Vector2(.16f,2.4f),0x7b725c,2,root,true);var closed=G("Closed leaf",root,new Vector2(x,floor));B("Wooden door edge",new Vector2(x,floor+1.15f),new Vector2(.15f,2.3f),0x7b725c,3,closed);var open=G("Open leaf",root,new Vector2(x,floor));B("Opened door",new Vector2(x+.36f,floor+1.15f),new Vector2(.65f,2.3f),0x5b594b,-4,open);open.gameObject.SetActive(false);var d=root.gameObject.AddComponent<RecoilDoor>();d.requiresClue=false;d.completesLevel=false;d.openStateItemId=id;d.openPrompt="E / OPEN OFFICE DOOR";d.travelPrompt="E / DOOR OPEN";d.firstOpenMessage="Office door opened.";d.openedMessage="The office door is open.";d.openingBarrier=barrier.GetComponent<BoxCollider2D>();d.closedVisual=closed;d.openVisual=open;var sr=barrier.GetComponent<SpriteRenderer>();sr.enabled=false;}
 static void Room(Transform parent,float x,float floor,int floorIndex,int roomIndex,string name){var root=G(name,parent,new Vector2(x,floor));B("Faded plaster",new Vector2(x+4.1f,floor+2),new Vector2(8.15f,3.9f),roomIndex==1?0x4e5750:0x596057,-9,root);B("Painted dado",new Vector2(x+4.1f,floor+.65f),new Vector2(8.15f,1.3f),0x35433c,-8,root);B("Skirting",new Vector2(x+4.1f,floor+.07f),new Vector2(8.15f,.1f),0x242d29,-7,root);Text("Room plaque",name,new Vector2(x+4.1f,floor+3.2f),root);B("Notice board",new Vector2(x+1.05f,floor+2.05f),new Vector2(1.2f,.85f),0x766647,-6,root);for(int i=0;i<3;i++)B("Faded document",new Vector2(x+.7f+i*.3f,floor+2),new Vector2(.21f,.36f),0x9f9b7e,-5,root);
  for(int i=0;i<2;i++){float dx=x+2.3f+i*3.25f;var desk=G("Desk - background furniture",root,new Vector2(dx,floor));B("Desk top",new Vector2(dx,floor+.85f),new Vector2(1.9f,.13f),0x8c785b,-4,desk);for(int k=-1;k<=1;k+=2)B("Desk leg",new Vector2(dx+k*.75f,floor+.42f),new Vector2(.1f,.8f),0x38423b,-4,desk);B("Drawer unit",new Vector2(dx+.5f,floor+.5f),new Vector2(.5f,.7f),0x68614f,-4,desk);B("Old terminal",new Vector2(dx-.35f,floor+1.2f),new Vector2(.5f,.55f),0x676e64,-3,desk);B("Unpowered screen",new Vector2(dx-.35f,floor+1.23f),new Vector2(.35f,.35f),0x152322,-2,desk);B("Chair seat",new Vector2(dx+.5f,floor+.5f),new Vector2(.55f,.12f),0x3c4237,-3,desk);B("Chair back",new Vector2(dx+.7f,floor+.88f),new Vector2(.15f,.65f),0x4e5747,-3,desk);}
  var cabinet=G("Filing cabinet",root,new Vector2(x+7.4f,floor));B("Steel cabinet",new Vector2(x+7.4f,floor+1.05f),new Vector2(.7f,2.1f),0x4d5a4e,-4,cabinet);for(int i=0;i<4;i++){B("Drawer seam",new Vector2(x+7.4f,floor+.3f+i*.46f),new Vector2(.63f,.025f),0x26342d,-3,cabinet);B("Drawer handle",new Vector2(x+7.4f,floor+.4f+i*.46f),new Vector2(.25f,.045f),0x899080,-2,cabinet);}
  var fixture=G("Office ceiling fixture",root,new Vector2(x+4.1f,floor+3.8f));B("Light housing",fixture.position,new Vector2(.8f,.09f),0x777b70,-3,fixture);var bulb=G("Light - fixture child",fixture,fixture.position);var l=bulb.gameObject.AddComponent<RecoilLight2D>();l.radius=2.8f;l.intensity=.24f;
