 public static void Refit(){
  if(EditorApplication.isPlaying)throw new Exception("Exit Play first.");var original=SceneManager.GetActiveScene();var loaded=Enumerable.Range(0,SceneManager.sceneCount).Select(i=>SceneManager.GetSceneAt(i).path).ToArray();var outside=Open("Assets/Scenes/RecoilPrototype.unity");var inside=Open("Assets/Scenes/RecoilFactoryInterior.unity");Backup(outside);Backup(inside);var ow=World(outside);var iw=World(inside);if(iw.GetComponentsInChildren<Transform>(true).Any(t=>t.name=="Office suites - factory refit"))throw new Exception("Refit already exists; edit the saved room objects.");var serialized=new SerializedObject(ow);square=(Sprite)serialized.FindProperty("sceneSprite").objectReferenceValue;material=(Material)serialized.FindProperty("sceneMaterial").objectReferenceValue;wall=Import("Assets/RecoilPrototype/Art/FactoryRefit/FactoryWallPlate.png");doorArt=Import("Assets/RecoilPrototype/Art/FactoryRefit/SteelFireExit.png");
  SceneManager.SetActiveScene(outside);var building=Find(ow,"Factory Building - four storeys");float left=building.position.x;var facade=Find(ow,"Factory main facade");facade.position=new Vector2(left+16,Height/2);facade.localScale=new Vector3(32/wall.bounds.size.x,Height/wall.bounds.size.y,1);var facadeRenderer=facade.GetComponent<SpriteRenderer>();facadeRenderer.sprite=wall;facadeRenderer.color=new Color(.5f,.55f,.53f,1);var side=Find(ow,"Left side elevation");side.position=new Vector2(left-.7f,Height/2);side.localScale=new Vector3(1.6f,Height,1);side.GetComponent<SpriteRenderer>().color=RecoilPrototype.Hex(0x303e38);
  foreach(var t in building.GetComponentsInChildren<Transform>(true).ToArray())if(t.name=="Factory window"||t.name=="Window mullion"||t.name=="Window crossbar"||t.name.StartsWith("Floor cornice")||t.name.StartsWith("FLOOR "))UnityEngine.Object.DestroyImmediate(t.gameObject);
  var detail=G("Facade - editable office windows and structural details",building,new Vector2(left,0));for(int f=0;f<4;f++){B("Storey belt course",new Vector2(left+16,levels[f]+.15f),new Vector2(32,.16f),0x6b7064,-5,detail);for(int n=0;n<4;n++)Window(detail,left+5+n*7.1f,levels[f]+(f==0?3.85f:2.15f),f==0);}for(int n=0;n<5;n++)B("Facade concrete pier",new Vector2(left+1+n*7.5f,Height/2),new Vector2(.23f,Height),0x6e7369,-5,detail);
  var parapet=Find(ow,"Factory parapet");parapet.position=new Vector2(left+16,Height+.2f);var ext=ow.GetComponentsInChildren<RecoilDoor>().First(d=>d.requiredItemId=="factory_shortcut_floor3");DoorArtwork(ext,levels[2]);B("Door recess shadow",new Vector2(ext.transform.position.x,levels[2]+1.3f),new Vector2(1.7f,2.7f),0x131c18,-1,detail);B("Exit rain canopy",new Vector2(ext.transform.position.x,levels[2]+2.7f),new Vector2(1.9f,.12f),0x64726a,4,detail);
  var exterior=Find(ow,"Exterior fire escape - W up S down");var flights=exterior.GetComponentsInChildren<WalkableStairway>().OrderBy(s=>s.routePoints[0].position.y).ToArray();foreach(var t in exterior.Cast<Transform>().ToArray())if(!t.GetComponent<WalkableStairway>())UnityEngine.Object.DestroyImmediate(t.gameObject);for(int i=0;i<flights.Length;i++)RebuildStair(flights[i],levels[i],levels[i+1],true);float access=flights[0].routePoints[0].position.x;for(int i=1;i<=2;i++){var balcony=B("Fire escape balcony",new Vector2(access+.25f,levels[i]-.1f),new Vector2(2.8f,.2f),0x5c6b63,1,exterior,true);balcony.AddComponent<SoftRoofPlatform>();balcony.GetComponent<BoxCollider2D>().isTrigger=true;Bar("Wall tie bracket",new Vector2(access-1.1f,levels[i]-.5f),new Vector2(left+.3f,levels[i]-.1f),.11f,0x48564d,0,exterior);}foreach(float x in new[]{access-5.8f,access}){B("Fire escape load-bearing column",new Vector2(x,levels[2]/2),new Vector2(.15f,levels[2]),0x414f48,-2,exterior);B("Column footing",new Vector2(x,.11f),new Vector2(.48f,.22f),0x747a6b,-1,exterior);}Find(ow,"Third Floor Fire Escape Spawn").position=new Vector2(access,levels[2]+.845f);foreach(var c in outside.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<RecoilCameraController>()))c.maximumY=30;
  EditorSceneManager.MarkSceneDirty(outside);EditorSceneManager.SaveScene(outside);
  SceneManager.SetActiveScene(inside);var ceiling=Find(iw,"Low Factory Ceiling");ceiling.position=new Vector2(17.5f,Height+.3f);foreach(string name in new[]{"Left Factory Wall","Right Factory Wall","Factory interior","Factory Dark Area"}){var t=Find(iw,name);t.position=new Vector2(t.position.x,Height/2);var scale=t.localScale;scale.y=Height;t.localScale=scale;}
  var additions=Find(iw,"Four-storey interior additions");foreach(var t in additions.GetComponentsInChildren<Transform>(true).ToArray())if(t && (t.name=="Upper wall seam"||t.name=="Upper floor conduit"||t.name=="Weak stairwell light"||t.name.StartsWith("FLOOR ")))UnityEngine.Object.DestroyImmediate(t.gameObject);for(int i=1;i<=3;i++)Find(iw,"Floor "+(i+1)+" - solid slab").position=new Vector2(14,levels[i]-.15f);var internalFlights=Find(iw,"Right Stairwell - continuous switchbacks").GetComponentsInChildren<WalkableStairway>().OrderBy(s=>s.routePoints[0].position.y).ToArray();for(int i=0;i<3;i++)RebuildStair(internalFlights[i],levels[i],levels[i+1],false);
  var suites=G("Office suites - factory refit",additions,Vector2.zero);string[,] names={{"ADMINISTRATION","STAFF ROOM","DOCUMENT ARCHIVE"},{"ACCOUNTS","SHIFT OFFICE","RECORDS"},{"MANAGER OFFICE","MEETING ROOM","PERSONNEL"}};for(int f=1;f<4;f++){for(int room=0;room<3;room++)Room(suites,room*8.5f+.2f,levels[f],f,room,names[f-1,room]);for(int partition=1;partition<=2;partition++)OfficeDoor(suites,partition*8.5f,levels[f],"factory_office_door_"+f+"_"+partition);Text("Floor label","FLOOR "+(f+1),new Vector2(27,levels[f]+3.4f),suites);}
  var inner=iw.GetComponentsInChildren<RecoilDoor>().First(d=>d.openStateItemId=="factory_shortcut_floor3");DoorArtwork(inner,levels[2]);Find(iw,"Third Floor Shortcut Spawn").position=new Vector2(2.4f,levels[2]+.845f);foreach(var c in inside.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<RecoilCameraController>()))c.maximumY=Height-2;
  EditorSceneManager.MarkSceneDirty(inside);EditorSceneManager.SaveScene(inside);AssetDatabase.SaveAssets();foreach(var path in new[]{outside.path,inside.path}){var s=SceneManager.GetSceneByPath(path);if(s.isLoaded&&!loaded.Contains(path))EditorSceneManager.CloseScene(s,true);}SceneManager.SetActiveScene(original);Debug.Log("FACTORY_OFFICE_REFIT_COMPLETE");
 }
 public static void FinishAndCapture(){
  var scene=EditorSceneManager.OpenScene("Assets/Scenes/RecoilPrototype.unity",OpenSceneMode.Single);var w=World(scene);var building=Find(w,"Factory Building - four storeys");var flight=Find(w,"Exterior fire escape - W up S down").GetComponentsInChildren<WalkableStairway>().OrderBy(s=>s.routePoints[0].position.y).First();float end=flight.routePoints[1].position.x-.9f;Physics2D.SyncTransforms();foreach(var c in w.GetComponentsInChildren<BoxCollider2D>()){var b=c.bounds;if(c.name=="Solid terrain" && b.size.x>15 && b.min.y>10 && b.max.y<16 && b.max.x>building.position.x){float left=b.min.x;c.transform.position=new Vector2((left+end)/2,c.transform.position.y);c.transform.localScale=new Vector3(end-left,c.transform.localScale.y,1);}}
  EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);scene=EditorSceneManager.OpenScene("Assets/Scenes/RecoilFactoryInterior.unity",OpenSceneMode.Single);w=World(scene);var stair=w.GetComponentsInChildren<WalkableStairway>().OrderBy(s=>s.routePoints[0].position.y).First();PrefabUtility.SaveAsPrefabAsset(stair.gameObject,"Assets/RecoilPrototype/Prefabs/WalkableSwitchbackStairway.prefab");AssetDatabase.SaveAssets();FourStoreyFactoryBuilder.CaptureLayout();Debug.Log("OFFICE_REFIT_CAPTURE_COMPLETE");
 }

